const M = window.MANIFEST;
const $ = (s, el = document) => el.querySelector(s);
const esc = s => s.replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

// ── desktop ──
const desktop = $('#desktop');
desktop.innerHTML = PROJECTS.map((p, i) => {
  const items = M[p.id];
  const [a, b] = p.video ? [M.khanqah[0], M.field[3]] : [items[0], items[1] || items[0]];
  return `
  <button class="folder" data-id="${p.id}" style="animation-delay:${i * 50}ms">
    <span class="f-icon">
      <span class="f-back"></span>
      <span class="f-paper p1" style="background-image:url('${a.thumb}')"></span>
      <span class="f-paper p2" style="background-image:url('${b.thumb}')"></span>
      <span class="f-front"><span class="f-tag">${esc(p.tag)}</span><span class="f-count">${items.length} ${p.video ? 'clips' : 'files'}</span></span>
    </span>
    <span class="f-label"><strong>${esc(p.title)}</strong><span>${esc(p.sub)}</span></span>
  </button>`;
}).join('');
desktop.addEventListener('click', e => {
  const f = e.target.closest('.folder');
  if (f) openWindow(f.dataset.id);
});

// ── search / filter ──
const q = $('#q'), empty = $('#empty'), state = $('#filterState');
function applyFilter(term) {
  const t = term.trim().toLowerCase();
  let shown = 0;
  desktop.querySelectorAll('.folder').forEach(el => {
    const p = PROJECTS.find(x => x.id === el.dataset.id);
    const hay = `${p.title} ${p.sub} ${p.tag} ${p.tags}`.toLowerCase();
    const ok = !t || t.split(/\s+/).every(w => hay.includes(w));
    el.hidden = !ok;
    el.classList.toggle('hit', ok && !!t);
    shown += ok;
  });
  empty.hidden = shown > 0;
  state.hidden = !t;
  if (t) state.innerHTML = `Showing ${shown} folder${shown === 1 ? '' : 's'} for “${esc(t)}” <button type="button" id="clearF">clear</button>`;
}
q.addEventListener('input', () => applyFilter(q.value));
$('#search').addEventListener('submit', e => {
  e.preventDefault();
  applyFilter(q.value);
  $('#work').scrollIntoView();
});
state.addEventListener('click', e => { if (e.target.id === 'clearF') { q.value = ''; applyFilter(''); } });
document.querySelectorAll('.band').forEach(b => b.addEventListener('click', () => {
  q.value = b.dataset.filter;
  applyFilter(q.value);
  $('#work').scrollIntoView();
}));

// ── folder window ──
const win = $('#win'), grid = $('#winGrid'), flipBtn = $('#flipBtn'), flipbook = $('#flipbook');
let current = null, flipTimer = null, lastFocus = null;

function openWindow(id) {
  const p = PROJECTS.find(x => x.id === id);
  current = p;
  lastFocus = document.activeElement;
  $('#winTitle').textContent = p.title;
  $('#winDesc').textContent = p.desc;
  $('#winPath').textContent = `~/rollnumberninee/work/${p.id}`;
  grid.innerHTML = M[id].map((it, i) => p.video
    ? `<button class="tile" data-i="${i}"><video src="${it.src}#t=0.5" muted playsinline preload="metadata"></video></button>`
    : `<button class="tile" data-i="${i}"><img src="${it.thumb}" width="${it.w}" height="${it.h}" loading="lazy" alt="${esc(p.title)} — ${i + 1}"></button>`
  ).join('');
  flipBtn.hidden = !p.flipbook;
  stopFlip();
  win.hidden = false;
  document.body.style.overflow = 'hidden';
  $('[data-close]', win).focus();
}
function closeWindow() {
  stopFlip();
  win.hidden = true;
  grid.innerHTML = '';
  document.body.style.overflow = '';
  lastFocus && lastFocus.focus();
}
grid.addEventListener('click', e => {
  const t = e.target.closest('.tile');
  if (t) openLightbox(M[current.id], +t.dataset.i, current.title, !!current.video);
});
win.addEventListener('click', e => { if (e.target === win || e.target.closest('[data-close]')) closeWindow(); });

function stopFlip() {
  clearInterval(flipTimer); flipTimer = null;
  flipbook.hidden = true;
  flipBtn.textContent = '▶ Play flipbook';
}
flipBtn.addEventListener('click', () => {
  if (flipTimer) return stopFlip();
  const frames = M.stopmotion, img = $('img', flipbook);
  frames.forEach(f => { new Image().src = f.src; });   // warm the cache
  let i = 0;
  img.src = frames[0].src;
  flipbook.hidden = false;
  flipBtn.textContent = '■ Stop';
  flipTimer = setInterval(() => { i = (i + 1) % frames.length; img.src = frames[i].src; }, 160);
});

// ── lightbox ──
const lb = $('#lb'), lbMedia = $('#lbMedia'), lbCap = $('#lbCap');
let lbList = [], lbIdx = 0, lbTitle = '', lbVideo = false;

function openLightbox(list, i, title, isVideo) {
  lbList = list; lbIdx = i; lbTitle = title; lbVideo = isVideo;
  lb.hidden = false;
  document.body.style.overflow = 'hidden';
  renderLb();
  $('.lb-close', lb).focus();
}
function renderLb() {
  const it = lbList[lbIdx];
  lbMedia.innerHTML = lbVideo
    ? `<video src="${it.src}" controls autoplay playsinline></video>`
    : `<img src="${it.src}" alt="${esc(lbTitle)} — ${lbIdx + 1}">`;
  lbCap.textContent = `${lbTitle} · ${lbIdx + 1} / ${lbList.length}`;
}
function stepLb(d) { lbIdx = (lbIdx + d + lbList.length) % lbList.length; renderLb(); }
function closeLb() {
  lb.hidden = true; lbMedia.innerHTML = '';
  document.body.style.overflow = win.hidden ? '' : 'hidden';
}
$('.lb-prev', lb).addEventListener('click', () => stepLb(-1));
$('.lb-next', lb).addEventListener('click', () => stepLb(1));
lb.addEventListener('click', e => { if (e.target === lb || e.target.closest('[data-close]')) closeLb(); });

document.addEventListener('keydown', e => {
  if (!lb.hidden) {
    if (e.key === 'Escape') closeLb();
    if (e.key === 'ArrowLeft') stepLb(-1);
    if (e.key === 'ArrowRight') stepLb(1);
  } else if (!win.hidden && e.key === 'Escape') closeWindow();
  else if (win.hidden && e.key === '/' && document.activeElement !== q) { e.preventDefault(); q.focus(); }
});

// ── film section ──
const reels = $('#reels');
reels.innerHTML = M.reels.map((r, i) => `
  <button class="reel" data-i="${i}" aria-label="Play edit ${i + 1}">
    <video src="${r.src}#t=0.5" muted loop playsinline preload="metadata"></video>
    <span class="reel-play">▶</span>
    <span class="reel-meta"><span>EDIT ${String(i + 1).padStart(2, '0')}</span><span>${r.mb} MB</span></span>
  </button>`).join('');
reels.querySelectorAll('.reel').forEach(el => {
  const v = $('video', el);
  el.addEventListener('mouseenter', () => v.play().catch(() => {}));
  el.addEventListener('mouseleave', () => v.pause());
  el.addEventListener('click', () => openLightbox(M.reels, +el.dataset.i, 'Edits & reels', true));
});

// ── selected work rail (drag to browse) ──
const FEATURED = ['pinjrakari', 'khanqah', 'casestudy', 'progress', 'abstraction', 'stopmotion', 'sketches'];
const rail = $('#rail');
rail.innerHTML = FEATURED.map((id, i) => {
  const p = PROJECTS.find(x => x.id === id), cover = M[id][0];
  return `
  <button class="card" data-id="${id}">
    <span class="card-img">
      <img src="${cover.src}" alt="${esc(p.title)}" loading="lazy" draggable="false">
      <span class="card-num">${String(i + 1).padStart(2, '0')} / ${String(FEATURED.length).padStart(2, '0')}</span>
      <span class="card-open">↗</span>
    </span>
    <span class="card-meta"><strong>${esc(p.title)}</strong><span>${esc(p.tag)}</span></span>
  </button>`;
}).join('');
{
  let down = false, startX = 0, startScroll = 0, moved = 0;
  rail.addEventListener('pointerdown', e => {
    if (e.pointerType !== 'mouse') return;           // touch scrolls natively
    down = true; moved = 0; startX = e.clientX; startScroll = rail.scrollLeft;
  });
  window.addEventListener('pointermove', e => {
    if (!down) return;
    const dx = e.clientX - startX;
    moved = Math.max(moved, Math.abs(dx));
    if (moved > 5) rail.classList.add('dragging');
    rail.scrollLeft = startScroll - dx;
  });
  window.addEventListener('pointerup', () => {
    down = false;
    requestAnimationFrame(() => rail.classList.remove('dragging'));
  });
  rail.addEventListener('click', e => {
    const c = e.target.closest('.card');
    if (c && moved <= 5) openWindow(c.dataset.id);
  });
}

// ── services list with cursor-following preview ──
const SERVICES = [
  ['Architectural design', 'Studio projects and form development, from bubble diagrams to plans.', 'progress', 1],
  ['Case-study analysis', 'Site context, access, structure and diagrams that explain how a building works.', 'casestudy', 2],
  ['Heritage documentation', 'Mapping and photographing Kashmir’s timber architecture and crafts.', 'khanqah', 0],
  ['Video editing', 'Short edits and reels from site visits, cut in Premiere Pro.', 'field', 0],
  ['Sketching & stop motion', 'Hand drawing, abstraction and frame-by-frame animation.', 'stopmotion', 0],
];
const svc = $('#svc'), preview = $('#svcPreview');
svc.innerHTML = SERVICES.map(([t, d, id], i) => `
  <li class="reveal"><button data-id="${id}" data-i="${i}">
    <span class="n">(${String(i + 1).padStart(2, '0')})</span><span class="t">${esc(t)}</span><span class="d">${esc(d)}</span>
  </button></li>`).join('');
svc.querySelectorAll('button').forEach(b => {
  const [, , id, n] = SERVICES[+b.dataset.i];
  b.addEventListener('mouseenter', () => { preview.src = M[id][n].thumb; preview.classList.add('on'); });
  b.addEventListener('mouseleave', () => preview.classList.remove('on'));
  b.addEventListener('click', () => {
    if (id === 'field') return $('#film').scrollIntoView();
    openWindow(id);
  });
});
svc.addEventListener('mousemove', e => { preview.style.left = e.clientX + 'px'; preview.style.top = e.clientY + 'px'; });

// ── stats count-up ──
const totals = {
  projects: PROJECTS.length,
  images: PROJECTS.filter(p => !p.video).reduce((n, p) => n + M[p.id].length, 0),
  reels: M.reels.length,
  frames: M.stopmotion.length,
};
function countUp(el) {
  const to = totals[el.dataset.to], t0 = performance.now(), dur = 1400;
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) return void (el.textContent = to);
  const step = now => {
    const k = Math.min(1, (now - t0) / dur);
    el.textContent = Math.round(to * (1 - Math.pow(1 - k, 3)));
    if (k < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

// ── scroll reveal ──
const io = new IntersectionObserver(entries => entries.forEach(en => {
  if (!en.isIntersecting) return;
  en.target.classList.add('in');
  const c = en.target.querySelector('.count');
  if (c) countUp(c);
  io.unobserve(en.target);
}), { threshold: .2 });
document.querySelectorAll('.reveal').forEach(el => io.observe(el));

// ── hero parallax floaters ──
const hero = $('.hero-frame'), floaters = [...document.querySelectorAll('.fl')];
if (matchMedia('(hover: hover) and (prefers-reduced-motion: no-preference)').matches) {
  hero.addEventListener('mousemove', e => {
    const r = hero.getBoundingClientRect();
    const nx = (e.clientX - r.left) / r.width - .5, ny = (e.clientY - r.top) / r.height - .5;
    floaters.forEach(f => {
      const d = +f.dataset.depth;
      f.style.setProperty('--x', `${-nx * d}px`);
      f.style.setProperty('--y', `${-ny * d}px`);
    });
  });
  hero.addEventListener('mouseleave', () => floaters.forEach(f => { f.style.setProperty('--x', '0px'); f.style.setProperty('--y', '0px'); }));
}
$('#showreel').addEventListener('click', () => openLightbox(M.reels, 0, 'Showreel', true));

// ── chrome ──
const clock = $('#clock');
const tickClock = () => { clock.textContent = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }); };
tickClock(); setInterval(tickClock, 30000);
$('#year').textContent = new Date().getFullYear();
